mapper.select:
SELECT p.id, p.user_id, p.section_id, p.title, p.content, p.images, p.like_count, p.comment_count, p.view_count, p.is_sticky, p.status, p.create_time, p.update_time, u.username AS author_username, d.avatar AS author_avatar, s.name AS section_name FROM forum_post p INNER JOIN sys_user u ON p.user_id = u.id INNER JOIN sys_user_detail d ON p.user_id = d.user_id INNER JOIN forum_section s ON p.section_id = s.id WHERE p.status = 1 AND s.status = 1
AND p.section_id = #{sectionId}
ORDER BY
p.is_sticky DESC, p.like_count DESC, p.comment_count DESC, p.create_time DESC
p.is_sticky DESC, p.create_time DESC
LIMIT #{offset}, #{size}

mapper.update:
UPDATE forum_post
SET like_count = like_count + #{delta}
WHERE id = #{id}

UPDATE forum_post
SET comment_count = comment_count + #{delta}
WHERE id = #{id}

UPDATE forum_post
SET view_count = view_count + #{delta}
WHERE id = #{id}
